import Foundation

/// Finds a Claude Code session's real title in its transcript: the name you gave it with
/// /rename (`custom-title`), or else the one Claude generated (`ai-title`). Transcripts grow to
/// megabytes, so only the tail is read, and only again once the file has grown.
public final class ClaudeTitles: @unchecked Sendable {
    public struct Title: Equatable, Sendable {
        public var text: String
        /// Set by you with /rename, rather than generated by Claude.
        public var isCustom: Bool
    }

    private struct Cached {
        var size: UInt64
        var checked: Date
        var title: Title?
    }

    private let projects: URL
    private let tailBytes: UInt64
    private var cache: [String: Cached] = [:]
    private let lock = NSLock()

    public init(projects: URL = FileManager.default.homeDirectoryForCurrentUser
        .appendingPathComponent(".claude/projects"), tailBytes: UInt64 = 512 * 1024) {
        self.projects = projects
        self.tailBytes = tailBytes
    }

    /// The best title for a session, or nil if the transcript has none yet.
    public func title(sessionId: String, cwd: String, now: Date = Date()) -> Title? {
        lock.lock()
        defer { lock.unlock() }
        guard let file = transcript(sessionId: sessionId, cwd: cwd),
              let size = (try? FileManager.default.attributesOfItem(atPath: file.path))?[.size] as? UInt64
        else { return cache[sessionId]?.title }

        if let cached = cache[sessionId],
           cached.size == size || now.timeIntervalSince(cached.checked) < 5 {
            return cached.title
        }
        let title = Self.latestTitle(in: file, size: size, tailBytes: tailBytes) ?? cache[sessionId]?.title
        cache[sessionId] = Cached(size: size, checked: now, title: title)
        return title
    }

    /// ~/.claude/projects/<cwd with every non-alphanumeric character as "-">/<session>.jsonl
    func transcript(sessionId: String, cwd: String) -> URL? {
        let folder = String(cwd.map { $0.isASCII && ($0.isLetter || $0.isNumber) ? $0 : "-" })
        let direct = projects.appendingPathComponent(folder).appendingPathComponent("\(sessionId).jsonl")
        return FileManager.default.fileExists(atPath: direct.path) ? direct : nil
    }

    static func latestTitle(in file: URL, size: UInt64, tailBytes: UInt64) -> Title? {
        guard let handle = try? FileHandle(forReadingFrom: file) else { return nil }
        defer { try? handle.close() }
        let start = size > tailBytes ? size - tailBytes : 0
        try? handle.seek(toOffset: start)
        guard let data = try? handle.readToEnd() else { return nil }
        return latestTitle(in: data)
    }

    /// The last custom title wins over any AI title; among AI titles, the last one.
    static func latestTitle(in data: Data) -> Title? {
        var custom: String?
        var ai: String?
        for line in data.split(separator: 0x0A) {
            // Cheap filter before parsing: almost every line is something else.
            guard line.count < 4096, let text = String(data: line, encoding: .utf8),
                  text.contains("-title\"")
            else { continue }
            guard let json = try? JSONSerialization.jsonObject(with: Data(line)) as? [String: Any],
                  let type = json["type"] as? String
            else { continue }
            if type == "custom-title", let value = json["customTitle"] as? String, !value.isEmpty {
                custom = value
            } else if type == "ai-title", let value = json["aiTitle"] as? String, !value.isEmpty {
                ai = value
            }
        }
        if let custom { return Title(text: custom, isCustom: true) }
        return ai.map { Title(text: $0, isCustom: false) }
    }
}
